    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3, 255))
    namedValues = NamedValues(("conferenceCall", 1), ("pointToPointCall", 2), ("monitoredCall", 3), ("other", 255))

